            self.field_b = b
            self.__pydantic_extra__ = {}
            if fields_set is not None:
                self.__pydantic_fields_set__ = fields_set

    v = SchemaValidator(
        core_schema.model_schema(
            cls=MyModel,
            revalidate_instances='always',
            schema=core_schema.model_fields_schema(
