            "pk": "primary_key_%(table_name)s_"
            "%(column_0_N_name)s"
            + (
                "_".join(
                    "".join(random.choice("abcdef") for j in range(30))
                    for i in range(10)
                )
            ),
        }
        metadata.naming_convention = convention

        a = Table(
            "a_things_with_stuff",
            metadata,
            Column("id_long_column_name", Integer, primary_key=True),
            Column("id_another_long_name", Integer, primary_key=True),
        )
        cons = a.primary_key
        actual_name = cons.name

        metadata.create_all(connection)
        insp = inspect(connection)
        pk = insp.get_pk_constraint("a_things_with_stuff")
        reflected_name = pk["name"]
        return actual_name, reflected_name

    def ix(self, metadata, connection):
        convention = {
            "ix": "index_%(table_name)s_"
            "%(column_0_N_name)s"
            + (
                "_".join(
                    "".join(random.choice("abcdef") for j in range(30))
                    for i in range(10)
                )
            ),
        }
        metadata.naming_convention = convention

        a = Table(
            "a_things_with_stuff",
            metadata,
            Column("id_long_column_name", Integer, primary_key=True),
            Column("id_another_long_name", Integer),
        )
        cons = Index(None, a.c.id_long_column_name, a.c.id_another_long_name)
        actual_name = cons.name

        metadata.create_all(connection)
        insp = inspect(connection)
        ix = insp.get_indexes("a_things_with_stuff")
        reflected_name = ix[0]["name"]
        return actual_name, reflected_name

    def uq(self, metadata, connection):
        convention = {
            "uq": "unique_constraint_%(table_name)s_"
            "%(column_0_N_name)s"
            + (
                "_".join(
                    "".join(random.choice("abcdef") for j in range(30))
                    for i in range(10)
                )
            ),
        }
        metadata.naming_convention = convention

        cons = UniqueConstraint("id_long_column_name", "id_another_long_name")
        Table(
            "a_things_with_stuff",
            metadata,
            Column("id_long_column_name", Integer, primary_key=True),
            Column("id_another_long_name", Integer),
            cons,
        )
        actual_name = cons.name

        metadata.create_all(connection)
        insp = inspect(connection)
        uq = insp.get_unique_constraints("a_things_with_stuff")
        reflected_name = uq[0]["name"]
        return actual_name, reflected_name

    def ck(self, metadata, connection):
        convention = {
            "ck": "check_constraint_%(table_name)s"
            + (
                "_".join(
                    "".join(random.choice("abcdef") for j in range(30))
                    for i in range(10)
                )
            ),
        }
        metadata.naming_convention = convention

        cons = CheckConstraint("some_long_column_name > 5")
        Table(
            "a_things_with_stuff",
            metadata,
            Column("id_long_column_name", Integer, primary_key=True),
            Column("some_long_column_name", Integer),
            cons,
        )
        actual_name = cons.name

        metadata.create_all(connection)
        insp = inspect(connection)
        ck = insp.get_check_constraints("a_things_with_stuff")
        reflected_name = ck[0]["name"]
        return actual_name, reflected_name

    @testing.combinations(
        ("fk",),
        ("pk",),
        ("ix",),
        ("ck", testing.requires.check_constraint_reflection.as_skips()),
        ("uq", testing.requires.unique_constraint_reflection.as_skips()),
        argnames="type_",
    )
    def test_long_convention_name(self, type_, metadata, connection):
        actual_name, reflected_name = getattr(self, type_)(
            metadata, connection
        )

        assert len(actual_name) > 255

        if reflected_name is not None:
            overlap = actual_name[0 : len(reflected_name)]
            if len(overlap) < len(actual_name):
                eq_(overlap[0:-5], reflected_name[0 : len(overlap) - 5])
            else:
                eq_(overlap, reflected_name)


__all__ = ("TableDDLTest", "FutureTableDDLTest", "LongNameBlowoutTest")

"""Consistency checks for the packaging metadata in pyproject.toml.

These catch mistakes that setuptools accepts silently but which break
other installers when building from the source distribution.

"""

import os
import re
import tomllib

from sqlalchemy.testing import eq_
from sqlalchemy.testing import fixtures


def _normalize_extra(name):
    # PEP 685 normalization, same as PEP 503 for project names
    return re.sub(r"[-_.]+", "-", name).lower()


def _self_referenced_extras(requirements):
    for req in requirements:
        if isinstance(req, str):
            m = re.match(r"\s*sqlalchemy\s*\[([^\]]*)\]", req, re.I)
            if m:
                yield from (e.strip() for e in m.group(1).split(","))


class PyprojectTest(fixtures.TestBase):
    @classmethod
    def setup_test_class(cls):
        here = os.path.dirname(__file__)
        path = os.path.normpath(
            os.path.join(here, "..", "..", "pyproject.toml")
        )
        with open(path, "rb") as file_:
            cls.pyproject = tomllib.load(file_)

    @property
    def extras(self):
        return self.pyproject["project"]["optional-dependencies"]

    def test_extras_unique_when_normalized(self):
        """test #13604"""

        seen = {}
        for name in self.extras:
            seen.setdefault(_normalize_extra(name), []).append(name)

        eq_({k: v for k, v in seen.items() if len(v) > 1}, {})

    def test_extras_are_normalized(self):
        eq_(
            [name for name in self.extras if _normalize_extra(name) != name],
            [],
        )

    def test_self_referenced_extras_exist(self):
        requirements = [
            req for reqs in self.extras.values() for req in reqs
        ] + [
            req
            for reqs in self.pyproject.get("dependency-groups", {}).values()
            for req in reqs
        ]

        eq_(
            sorted(
                name
                for name in _self_referenced_extras(requirements)
                if name not in self.extras
            ),
            [],
        )

