            ser = self._series[0]
            textplot(ser.expr, ser.start, ser.end)

    def close(self):
        pass

"""
Interval Arithmetic for plotting.
This module does not implement interval arithmetic accurately and
hence cannot be used for purposes other than plotting. If you want
to use interval arithmetic, use mpmath's interval arithmetic.

The module implements interval arithmetic using numpy and
python floating points. The rounding up and down is not handled
and hence this is not an accurate implementation of interval
arithmetic.

The module uses numpy for speed which cannot be achieved with mpmath.
"""

# Q: Why use numpy? Why not simply use mpmath's interval arithmetic?
# A: mpmath's interval arithmetic simulates a floating point unit
# and hence is slow, while numpy evaluations are orders of magnitude
# faster.

# Q: Why create a separate class for intervals? Why not use SymPy's
# Interval Sets?
# A: The functionalities that will be required for plotting is quite
# different from what Interval Sets implement.

# Q: Why is rounding up and down according to IEEE754 not handled?
# A: It is not possible to do it in both numpy and python. An external
# library has to used, which defeats the whole purpose i.e., speed. Also
# rounding is handled for very few functions in those libraries.

# Q Will my plots be affected?
# A It will not affect most of the plots. The interval arithmetic
# module based suffers the same problems as that of floating point
# arithmetic.
from __future__ import annotations

from sympy.core.numbers import int_valued
from sympy.core.logic import fuzzy_and
from sympy.simplify.simplify import nsimplify

from .interval_membership import intervalMembership


class interval:
    """ Represents an interval containing floating points as start and
    end of the interval
    The is_valid variable tracks whether the interval obtained as the
    result of the function is in the domain and is continuous.
    - True: Represents the interval result of a function is continuous and
            in the domain of the function.
    - False: The interval argument of the function was not in the domain of
             the function, hence the is_valid of the result interval is False
    - None: The function was not continuous over the interval or
            the function's argument interval is partly in the domain of the
            function

    A comparison between an interval and a real number, or a
    comparison between two intervals may return ``intervalMembership``
    of two 3-valued logic values.
    """

    def __init__(self, *args, is_valid=True, **kwargs):
        self.is_valid = is_valid
        if len(args) == 1:
            if isinstance(args[0], interval):
                self.start, self.end = args[0].start, args[0].end
            else:
                self.start = float(args[0])
                self.end = float(args[0])
        elif len(args) == 2:
            if args[0] < args[1]:
                self.start = float(args[0])
                self.end = float(args[1])
            else:
                self.start = float(args[1])
                self.end = float(args[0])

        else:
            raise ValueError("interval takes a maximum of two float values "
                            "as arguments")

    @property
    def mid(self):
        return (self.start + self.end) / 2.0

    @property
    def width(self):
        return self.end - self.start

    def __repr__(self):
        return "interval(%f, %f)" % (self.start, self.end)

    def __str__(self):
        return "[%f, %f]" % (self.start, self.end)

    def __lt__(self, other):
        if isinstance(other, (int, float)):
            if self.end < other:
                return intervalMembership(True, self.is_valid)
            elif self.start > other:
                return intervalMembership(False, self.is_valid)
            else:
                return intervalMembership(None, self.is_valid)

        elif isinstance(other, interval):
            valid = fuzzy_and([self.is_valid, other.is_valid])
            if self.end < other. start:
                return intervalMembership(True, valid)
            if self.start > other.end:
                return intervalMembership(False, valid)
            return intervalMembership(None, valid)
        else:
            return NotImplemented

    def __gt__(self, other):
        if isinstance(other, (int, float)):
            if self.start > other:
                return intervalMembership(True, self.is_valid)
            elif self.end < other:
                return intervalMembership(False, self.is_valid)
            else:
                return intervalMembership(None, self.is_valid)
        elif isinstance(other, interval):
            return other.__lt__(self)
        else:
            return NotImplemented

    def __eq__(self, other):
        if isinstance(other, (int, float)):
            if self.start == other and self.end == other:
                return intervalMembership(True, self.is_valid)
            if other in self:
                return intervalMembership(None, self.is_valid)
            else:
                return intervalMembership(False, self.is_valid)

        if isinstance(other, interval):
            valid = fuzzy_and([self.is_valid, other.is_valid])
            if self.start == other.start and self.end == other.end:
                return intervalMembership(True, valid)
            elif self.__lt__(other)[0] is not None:
                return intervalMembership(False, valid)
            else:
                return intervalMembership(None, valid)
        else:
            return NotImplemented

    def __ne__(self, other):
        if isinstance(other, (int, float)):
            if self.start == other and self.end == other:
                return intervalMembership(False, self.is_valid)
            if other in self:
                return intervalMembership(None, self.is_valid)
            else:
                return intervalMembership(True, self.is_valid)

        if isinstance(other, interval):
            valid = fuzzy_and([self.is_valid, other.is_valid])
            if self.start == other.start and self.end == other.end:
                return intervalMembership(False, valid)
            if not self.__lt__(other)[0] is None:
                return intervalMembership(True, valid)
            return intervalMembership(None, valid)
        else:
            return NotImplemented

    def __le__(self, other):
        if isinstance(other, (int, float)):
            if self.end <= other:
                return intervalMembership(True, self.is_valid)
            if self.start > other:
                return intervalMembership(False, self.is_valid)
            else:
                return intervalMembership(None, self.is_valid)

        if isinstance(other, interval):
            valid = fuzzy_and([self.is_valid, other.is_valid])
            if self.end <= other.start:
                return intervalMembership(True, valid)
            if self.start > other.end:
                return intervalMembership(False, valid)
            return intervalMembership(None, valid)
        else:
            return NotImplemented

    def __ge__(self, other):
        if isinstance(other, (int, float)):
            if self.start >= other:
                return intervalMembership(True, self.is_valid)
            elif self.end < other:
                return intervalMembership(False, self.is_valid)
            else:
                return intervalMembership(None, self.is_valid)
        elif isinstance(other, interval):
            return other.__le__(self)

    def __add__(self, other):
        if isinstance(other, (int, float)):
            if self.is_valid:
                return interval(self.start + other, self.end + other)
            else:
                start = self.start + other
                end = self.end + other
                return interval(start, end, is_valid=self.is_valid)

        elif isinstance(other, interval):
            start = self.start + other.start
            end = self.end + other.end
            valid = fuzzy_and([self.is_valid, other.is_valid])
            return interval(start, end, is_valid=valid)
        else:
            return NotImplemented

    __radd__ = __add__

    def __sub__(self, other):
        if isinstance(other, (int, float)):
            start = self.start - other
            end = self.end - other
            return interval(start, end, is_valid=self.is_valid)

        elif isinstance(other, interval):
            start = self.start - other.end
            end = self.end - other.start
            valid = fuzzy_and([self.is_valid, other.is_valid])
            return interval(start, end, is_valid=valid)
        else:
            return NotImplemented

    def __rsub__(self, other):
        if isinstance(other, (int, float)):
            start = other - self.end
            end = other - self.start
            return interval(start, end, is_valid=self.is_valid)
        elif isinstance(other, interval):
            return other.__sub__(self)
        else:
            return NotImplemented

    def __neg__(self):
        if self.is_valid:
            return interval(-self.end, -self.start)
        else:
            return interval(-self.end, -self.start, is_valid=self.is_valid)

    def __mul__(self, other):
        if isinstance(other, interval):
            if self.is_valid is False or other.is_valid is False:
                return interval(-float('inf'), float('inf'), is_valid=False)
            elif self.is_valid is None or other.is_valid is None:
                return interval(-float('inf'), float('inf'), is_valid=None)
            else:
                inters = []
                inters.append(self.start * other.start)
                inters.append(self.end * other.start)
                inters.append(self.start * other.end)
                inters.append(self.end * other.end)
                start = min(inters)
                end = max(inters)
                return interval(start, end)
        elif isinstance(other, (int, float)):
            return interval(self.start*other, self.end*other, is_valid=self.is_valid)
        else:
            return NotImplemented

    __rmul__ = __mul__

    def __contains__(self, other):
        if isinstance(other, (int, float)):
            return self.start <= other and self.end >= other
        else:
            return self.start <= other.start and other.end <= self.end

    def __rtruediv__(self, other):
        if isinstance(other, (int, float)):
            other = interval(other)
            return other.__truediv__(self)
        elif isinstance(other, interval):
            return other.__truediv__(self)
        else:
            return NotImplemented

    def __truediv__(self, other):
        # Both None and False are handled
        if not self.is_valid:
            # Don't divide as the value is not valid
            return interval(-float('inf'), float('inf'), is_valid=self.is_valid)
        if isinstance(other, (int, float)):
            if other == 0:
                # Divide by zero encountered. valid nowhere
                return interval(-float('inf'), float('inf'), is_valid=False)
            else:
                return interval(self.start / other, self.end / other)

        elif isinstance(other, interval):
            if other.is_valid is False or self.is_valid is False:
                return interval(-float('inf'), float('inf'), is_valid=False)
            elif other.is_valid is None or self.is_valid is None:
                return interval(-float('inf'), float('inf'), is_valid=None)
            else:
               # denominator contains both signs, i.e. being divided by zero
               # return the whole real line with is_valid = None
                if 0 in other:
                    return interval(-float('inf'), float('inf'), is_valid=None)

                # denominator negative
                this = self
                if other.end < 0:
                    this = -this
                    other = -other

                # denominator positive
                inters = []
                inters.append(this.start / other.start)
                inters.append(this.end / other.start)
                inters.append(this.start / other.end)
                inters.append(this.end / other.end)
                start = max(inters)
                end = min(inters)
                return interval(start, end)
        else:
            return NotImplemented

    def __pow__(self, other):
        # Implements only power to an integer.
        from .lib_interval import exp, log
        if not self.is_valid:
            return self
        if isinstance(other, interval):
            return exp(other * log(self))
        elif isinstance(other, (float, int)):
            if other < 0:
                return 1 / self.__pow__(abs(other))
            else:
                if int_valued(other):
                    return _pow_int(self, other)
                else:
                    return _pow_float(self, other)
        else:
            return NotImplemented

    def __rpow__(self, other):
        if isinstance(other, (float, int)):
            if not self.is_valid:
                #Don't do anything
                return self
            elif other < 0:
                if self.width > 0:
                    return interval(-float('inf'), float('inf'), is_valid=False)
                else:
                    power_rational = nsimplify(self.start)
                    num, denom = power_rational.as_numer_denom()
                    if denom % 2 == 0:
                        return interval(-float('inf'), float('inf'),
                                        is_valid=False)
                    else:
                        start = -abs(other)**self.start
                        end = start
                        return interval(start, end)
            else:
                return interval(other**self.start, other**self.end)
        elif isinstance(other, interval):
            return other.__pow__(self)
        else:
            return NotImplemented

    def __hash__(self):
        return hash((self.is_valid, self.start, self.end))


def _pow_float(inter, power):
    """Evaluates an interval raised to a floating point."""
    power_rational = nsimplify(power)
    num, denom = power_rational.as_numer_denom()
    if num % 2 == 0:
        start = abs(inter.start)**power
        end = abs(inter.end)**power
        if start < 0:
            ret = interval(0, max(start, end))
        else:
            ret = interval(start, end)
        return ret
    elif denom % 2 == 0:
        if inter.end < 0:
            return interval(-float('inf'), float('inf'), is_valid=False)
        elif inter.start < 0:
            return interval(0, inter.end**power, is_valid=None)
        else:
            return interval(inter.start**power, inter.end**power)
    else:
        if inter.start < 0:
            start = -abs(inter.start)**power
        else:
            start = inter.start**power

        if inter.end < 0:
            end = -abs(inter.end)**power
        else:
            end = inter.end**power

        return interval(start, end, is_valid=inter.is_valid)


def _pow_int(inter, power):
    """Evaluates an interval raised to an integer power"""
    power = int(power)
    if power & 1:
        return interval(inter.start**power, inter.end**power)
    else:
        if inter.start < 0 and inter.end > 0:
            start = 0
            end = max(inter.start**power, inter.end**power)
            return interval(start, end)
        else:
            return interval(inter.start**power, inter.end**power)

"""Implementation of :class:`FractionField` class. """

from __future__ import annotations
from typing import Generic, TYPE_CHECKING

from sympy.polys.domains.domain import Er
from sympy.polys.domains.compositedomain import CompositeDomain
from sympy.polys.domains.field import Field
from sympy.polys.polyerrors import CoercionFailed, GeneratorsError
from sympy.utilities import public


if TYPE_CHECKING:
    import sys
    if sys.version_info >= (3, 13):
        from typing import TypeIs
    else:
        from typing_extensions import TypeIs
    from sympy.polys.domains.domain import Domain
    from sympy.polys.fields import FracField, FracElement


@public
class FractionField(Field, CompositeDomain, Generic[Er]):
    """A class for representing multivariate rational function fields. """

    is_FractionField = is_Frac = True

    has_assoc_Ring = True
    has_assoc_Field = True

    def __init__(self, domain_or_field: FracField[Er] | Domain[Er], symbols=None, order=None):
        from sympy.polys.fields import FracField

        if isinstance(domain_or_field, FracField) and symbols is None and order is None:
            field = domain_or_field
        else:
            field = FracField(symbols, domain_or_field, order) # type: ignore

        self.field: FracField[Er] = field
        self.dtype = field.dtype

        self.gens = field.gens
        self.ngens = field.ngens
        self.symbols = field.symbols
        self.domain = field.domain

        # TODO: remove this
        self.dom = self.domain

    def new(self, element):
        return self.field.field_new(element)

    def of_type(self, element) -> TypeIs[FracElement[Er]]:
        """Check if ``a`` is of type ``dtype``. """
        return self.field.is_element(element)

    @property
    def zero(self):
        return self.field.zero

    @property
    def one(self):
        return self.field.one

    @property
    def order(self):
        return self.field.order

    def __str__(self):
        return str(self.domain) + '(' + ','.join(map(str, self.symbols)) + ')'

    def __hash__(self):
        return hash((self.__class__.__name__, self.field, self.domain, self.symbols))

    def __eq__(self, other):
        """Returns ``True`` if two domains are equivalent. """
        if not isinstance(other, FractionField):
            return NotImplemented
        return self.field == other.field

    def to_sympy(self, a):
        """Convert ``a`` to a SymPy object. """
        return a.as_expr()

    def from_sympy(self, a):
        """Convert SymPy's expression to ``dtype``. """
        return self.field.from_expr(a)

    def from_ZZ(K1, a, K0):
        """Convert a Python ``int`` object to ``dtype``. """
        return K1(K1.domain.convert(a, K0))

    def from_ZZ_python(K1, a, K0):
        """Convert a Python ``int`` object to ``dtype``. """
        return K1(K1.domain.convert(a, K0))

    def from_QQ(K1, a, K0):
        """Convert a Python ``Fraction`` object to ``dtype``. """
        dom = K1.domain
        conv = dom.convert_from
        if dom.is_ZZ:
            return K1(conv(K0.numer(a), K0)) / K1(conv(K0.denom(a), K0))
        else:
            return K1(conv(a, K0))

    def from_QQ_python(K1, a, K0):
        """Convert a Python ``Fraction`` object to ``dtype``. """
        return K1(K1.domain.convert(a, K0))

    def from_ZZ_gmpy(K1, a, K0):
        """Convert a GMPY ``mpz`` object to ``dtype``. """
        return K1(K1.domain.convert(a, K0))

    def from_QQ_gmpy(K1, a, K0):
        """Convert a GMPY ``mpq`` object to ``dtype``. """
        return K1(K1.domain.convert(a, K0))

    def from_GaussianRationalField(K1, a, K0):
        """Convert a ``GaussianRational`` object to ``dtype``. """
        return K1(K1.domain.convert(a, K0))

    def from_GaussianIntegerRing(K1, a, K0):
        """Convert a ``GaussianInteger`` object to ``dtype``. """
        return K1(K1.domain.convert(a, K0))

    def from_RealField(K1, a, K0):
        """Convert a mpmath ``mpf`` object to ``dtype``. """
        return K1(K1.domain.convert(a, K0))

    def from_ComplexField(K1, a, K0):
        """Convert a mpmath ``mpf`` object to ``dtype``. """
        return K1(K1.domain.convert(a, K0))

    def from_AlgebraicField(K1, a, K0):
        """Convert an algebraic number to ``dtype``. """
        if K1.domain != K0:
            a = K1.domain.convert_from(a, K0)
        if a is not None:
            return K1.new(a)

    def from_PolynomialRing(K1, a, K0):
        """Convert a polynomial to ``dtype``. """
        if a.is_ground:
            return K1.convert_from(a.coeff(1), K0.domain)
        try:
            return K1.new(a.set_ring(K1.field.ring))
        except (CoercionFailed, GeneratorsError):
            # XXX: We get here if K1=ZZ(x,y) and K0=QQ[x,y]
            # and the poly a in K0 has non-integer coefficients.
            # It seems that K1.new can handle this but K1.new doesn't work
            # when K0.domain is an algebraic field...
            try:
                return K1.new(a)
            except (CoercionFailed, GeneratorsError):
                return None

    def from_FractionField(K1, a, K0):
        """Convert a rational function to ``dtype``. """
        try:
            return a.set_field(K1.field)
        except (CoercionFailed, GeneratorsError):
            return None

    def get_ring(self):
        """Returns a field associated with ``self``. """
        return self.field.to_ring().to_domain()

    def is_positive(self, a):
        """Returns True if ``LC(a)`` is positive. """
        return self.domain.is_positive(a.numer.LC)

    def is_negative(self, a):
        """Returns True if ``LC(a)`` is negative. """
        return self.domain.is_negative(a.numer.LC)

    def is_nonpositive(self, a):
        """Returns True if ``LC(a)`` is non-positive. """
        return self.domain.is_nonpositive(a.numer.LC)

    def is_nonnegative(self, a):
        """Returns True if ``LC(a)`` is non-negative. """
        return self.domain.is_nonnegative(a.numer.LC)

    def numer(self, a):
        """Returns numerator of ``a``. """
        return a.numer

    def denom(self, a):
        """Returns denominator of ``a``. """
        return a.denom

    def factorial(self, a):
        """Returns factorial of ``a``. """
        return self.dtype(self.domain.factorial(a))

"""Low-level sparse polynomial operations on raw dict representations.

These helpers deliberately do not depend on PolyRing or PolyElement.
They operate on dicts mapping exponent tuples to coefficients and use
only the provided domain and number of variables.
"""

from __future__ import annotations

from itertools import combinations
from typing import TYPE_CHECKING, Mapping, Sequence, TypeVar

from sympy.core.intfunc import igcd
from sympy.ntheory.multinomial import multinomial_coefficients
from sympy.polys.monomials import MonomialOps, monom
from sympy.polys.orderings import lex, MonomialOrder
from sympy.polys.polyerrors import ExactQuotientFailed

if TYPE_CHECKING:
    from collections.abc import Callable

    from sympy.polys.domains.domain import Domain, Er

_T = TypeVar("_T")

smp = dict[monom, _T]


def _get_monomial_mul(n: int) -> Callable[[monom, monom], monom]:
    if n:
        return MonomialOps(n).mul()
    return lambda a, b: ()


def _get_monomial_mulpow(n: int) -> Callable[[monom, monom, int], monom]:
    if n:
        return MonomialOps(n).mulpow()
    return lambda a, b, k: ()


def _get_monomial_div(
    n: int,
) -> Callable[[monom, monom], monom | None]:
    if n:
        return MonomialOps(n).div()
    return lambda a, b: ()


def smp_add(f: smp[Er], g: smp[Er], domain: Domain[Er], n: int) -> smp[Er]:
    # Add two sparse polynomials and return a new dictionary.
    h = f.copy()
    _smp_iadd(h, g, n, domain)
    return h


def _smp_iadd(f: smp[Er], g: smp[Er], n: int, domain: Domain[Er]) -> None:
    # Add one sparse polynomial to another in place.
    zero = domain.zero
    for mon, coeff in g.items():
        coeff = f.get(mon, zero) + coeff
        if coeff:
            f[mon] = coeff
        elif mon in f:
            del f[mon]


def smp_mul(f: smp[Er], g: smp[Er], domain: Domain[Er], n: int) -> smp[Er]:
    # Multiply two sparse polynomials and return a new dictionary.
    zero = domain.zero
    h: smp[Er] = {}
    monomial_mul = _get_monomial_mul(n)
    for mon1, coeff1 in f.items():
        for mon2, coeff2 in g.items():
            mon = monomial_mul(mon1, mon2)
            coeff = h.get(mon, zero) + coeff1 * coeff2
            if coeff:
                h[mon] = coeff
            elif mon in h:
                del h[mon]
    return h


def smp_sub(f: smp[Er], g: smp[Er], domain: Domain[Er], n: int) -> smp[Er]:
    # Subtract one sparse polynomial from another.
    h = f.copy()
    _smp_isub(h, g, n, domain)
    return h


def _smp_isub(f: smp[Er], g: smp[Er], n: int, domain: Domain[Er]) -> None:
    # Subtract one sparse polynomial from another in place.
    zero = domain.zero
    for mon, coeff in g.items():
        coeff = f.get(mon, zero) - coeff
        if coeff:
            f[mon] = coeff
        elif mon in f:
            del f[mon]


def smp_degree(d: smp[Er], i_gen: int, n: int, domain: Domain[Er]) -> int:
    # Return the leading degree in one variable.
    if not d:
        return -1
    elif i_gen < 0:
        return 0
    else:
        return max(mon[i_gen] for mon in d)


def smp_degrees(d: smp[Er], n: int, domain: Domain[Er]) -> tuple[int, ...]:
    # Return the leading degrees in all variables.
    if not d:
        return (-1,) * n
    else:
        return tuple(max(mon[i] for mon in d) for i in range(n))


def smp_tail_degree(d: smp[Er], i_gen: int, n: int, domain: Domain[Er]) -> int:
    # Return the tail degree in one variable.
    if not d:
        return -1
    elif i_gen < 0:
        return 0
    else:
        return min(mon[i_gen] for mon in d)


def smp_tail_degrees(d: smp[Er], n: int, domain: Domain[Er]) -> tuple[int, ...]:
    # Return the tail degrees in all variables.
    if not d:
        return (-1,) * n
    else:
        return tuple(min(mon[i] for mon in d) for i in range(n))


def smp_diff(d: smp[Er], i_gen: int, n: int, domain: Domain[Er]) -> smp[Er]:
    # Differentiate a sparse polynomial with respect to one variable.
    h: smp[Er] = {}
    for mon, coeff in d.items():
        exp = mon[i_gen]
        if exp:
            new_mon = mon[:i_gen] + (exp - 1,) + mon[i_gen + 1 :]
            new_coeff = domain.convert(coeff * exp)
            if new_coeff:
                h[new_mon] = new_coeff
    return h


def smp_coeff_wrt(
    d: smp[Er], x_index: int, deg: int, n: int, domain: Domain[Er]
) -> smp[Er]:
    # Extract the coefficient wrt one variable of a fixed degree.
    h: smp[Er] = {}
    for mon, coeff in d.items():
        if mon[x_index] == deg:
            new_mon = mon[:x_index] + (0,) + mon[x_index + 1 :]
            h[new_mon] = coeff
    return h


def smp_deflate(
    polys: Sequence[smp[Er]], n: int, domain: Domain[Er]
) -> tuple[tuple[int, ...], Sequence[smp[Er]]]:
    # Deflate sparse polynomial exponents by their coordinate-wise gcd.
    J = [0] * n
    for d in polys:
        for mon in d:
            for i, exp in enumerate(mon):
                J[i] = igcd(J[i], exp)

    for i, gcd_exp in enumerate(J):
        if not gcd_exp:
            J[i] = 1

    J_tuple = tuple(J)

    if all(gcd_exp == 1 for gcd_exp in J_tuple):
        return J_tuple, polys

    return J_tuple, smp_deflate_by(polys, J_tuple, n, domain)


def smp_deflate_by(
    polys: Sequence[smp[Er]], J: Sequence[int], n: int, domain: Domain[Er]
) -> list[smp[Er]]:
    # Deflate sparse polynomial exponents by given coordinate-wise factors.
    deflated = []
    for d in polys:
        h: smp[Er] = {}
        for mon, coeff in d.items():
            new_mon = tuple(exp // gcd_exp for exp, gcd_exp in zip(mon, J))
            h[new_mon] = coeff
        deflated.append(h)

    return deflated


def smp_inflate(d: smp[Er], J: Sequence[int], n: int, domain: Domain[Er]) -> smp[Er]:
    # Inflate sparse polynomial exponents by coordinate-wise factors.
    h: smp[Er] = {}
    for mon, coeff in d.items():
        new_mon = tuple(exp * factor for exp, factor in zip(mon, J))
        h[new_mon] = coeff
    return h


def smp_content(d: smp[Er], n: int, domain: Domain[Er]) -> Er:
    # Return the gcd of all sparse polynomial coefficients.
    cont = domain.zero
    gcd = domain.gcd

    for coeff in d.values():
        cont = gcd(cont, coeff)

    return cont


def smp_primitive(d: smp[Er], n: int, domain: Domain[Er]) -> tuple[Er, smp[Er]]:
    # Return the content and primitive part of a sparse polynomial.
    h = d.copy()
    cont = _smp_iprimitive(h, n, domain)
    return cont, h


def _smp_iprimitive(d: smp[Er], n: int, domain: Domain[Er]) -> Er:
    # Make a sparse polynomial primitive in place and return its content.
    cont = smp_content(d, n, domain)
    if cont != domain.zero:
        _smp_iquo_ground(d, cont, n, domain)
    return cont


def smp_clear_denoms(d: smp[Er], n: int, domain: Domain[Er]) -> tuple[Er, smp[Er]]:
    # Clear denominators from sparse polynomial coefficients.
    h = d.copy()
    common = _smp_iclear_denoms(h, n, domain)
    return common, h


def _smp_iclear_denoms(d: smp[Er], n: int, domain: Domain[Er]) -> Er:
    # Clear denominators from sparse polynomial coefficients in place.
    if not domain.is_Field or not domain.has_assoc_Ring:
        return domain.one

    ground_ring = domain.get_ring()
    common = ground_ring.one
    lcm = ground_ring.lcm
    denom = domain.denom

    for coeff in d.values():
        common = lcm(common, denom(coeff))

    for mon, coeff in list(d.items()):
        new_coeff = coeff * common
        if new_coeff:
            d[mon] = new_coeff
        else:
            del d[mon]

    return common


def smp_is_zero(d: smp[Er], n: int, domain: Domain[Er]) -> bool:
    # Return whether a sparse polynomial is zero.
    return not d


def smp_is_one(d: smp[Er], n: int, domain: Domain[Er]) -> bool:
    # Return whether a sparse polynomial is one.
    zm = (0,) * n
    return len(d) == 1 and domain.is_one(d.get(zm, domain.zero))


def smp_is_ground(d: smp[Er], n: int, domain: Domain[Er]) -> bool:
    # Return whether a sparse polynomial is constant.
    return not d or (len(d) == 1 and (0,) * n in d)


def smp_is_term(d: smp[Er], n: int, domain: Domain[Er]) -> bool:
    # Return whether a sparse polynomial has at most one term.
    return len(d) <= 1


def smp_is_monomial(
    d: smp[Er], n: int, domain: Domain[Er], order: MonomialOrder = lex
) -> bool:
    # Return whether a sparse polynomial is zero or one monic term.
    return not d or (len(d) == 1 and smp_LC(d, n, domain, order) == 1)


def smp_is_negative(
    d: smp[Er], n: int, domain: Domain[Er], order: MonomialOrder = lex
) -> bool:
    # Return whether the leading coefficient is negative.
    return domain.is_negative(smp_LC(d, n, domain, order))


def smp_is_positive(
    d: smp[Er], n: int, domain: Domain[Er], order: MonomialOrder = lex
) -> bool:
    # Return whether the leading coefficient is positive.
    return domain.is_positive(smp_LC(d, n, domain, order))


def smp_is_nonnegative(
    d: smp[Er], n: int, domain: Domain[Er], order: MonomialOrder = lex
) -> bool:
    # Return whether the leading coefficient is nonnegative.
    return domain.is_nonnegative(smp_LC(d, n, domain, order))


def smp_is_nonpositive(
    d: smp[Er], n: int, domain: Domain[Er], order: MonomialOrder = lex
) -> bool:
    # Return whether the leading coefficient is nonpositive.
    return domain.is_nonpositive(smp_LC(d, n, domain, order))


def smp_is_monic(
    d: smp[Er], n: int, domain: Domain[Er], order: MonomialOrder = lex
) -> bool:
    # Return whether the leading coefficient is one.
    return domain.is_one(smp_LC(d, n, domain, order))


def smp_is_primitive(d: smp[Er], n: int, domain: Domain[Er]) -> bool:
    # Return whether the content is one.
    return domain.is_one(smp_content(d, n, domain))


def smp_is_linear(d: smp[Er], n: int, domain: Domain[Er]) -> bool:
    # Return whether every monomial has total degree at most one.
    return all(sum(mon) <= 1 for mon in d)


def smp_is_quadratic(d: smp[Er], n: int, domain: Domain[Er]) -> bool:
    # Return whether every monomial has total degree at most two.
    return all(sum(mon) <= 2 for mon in d)


def smp_iadd_monom(
    d: smp[Er], term: tuple[monom, Er], n: int, domain: Domain[Er]
) -> smp[Er]:
    # Add one term to a sparse polynomial in place.
    mon, coeff = term
    coeff = d.get(mon, domain.zero) + coeff
    if coeff:
        d[mon] = coeff
    elif mon in d:
        del d[mon]
    return d


def smp_iadd_poly_monom(
    d1: smp[Er], d2: smp[Er], term: tuple[monom, Er], n: int, domain: Domain[Er]
) -> smp[Er]:
    # Add d2 multiplied by one term to d1 in place.
    term_mon, term_coeff = term
    zero = domain.zero
    monomial_mul = _get_monomial_mul(n)

    for mon, coeff in d2.items():
        p_mon = monomial_mul(mon, term_mon)
        c = d1.get(p_mon, zero) + coeff * term_coeff
        if c:
            d1[p_mon] = c
        elif p_mon in d1:
            del d1[p_mon]

    return d1


def smp_add_ground(d: smp[Er], c: Er, n: int, domain: Domain[Er]) -> smp[Er]:
    # Add a ground coefficient to the constant term.
    h = d.copy()
    _smp_iadd_ground(h, c, n, domain)
    return h


def _smp_iadd_ground(d: smp[Er], c: Er, n: int, domain: Domain[Er]) -> None:
    # Add a ground coefficient to a sparse polynomial in place.
    if not c:
        return

    zm: monom = (0,) * n
    coeff = d.get(zm, domain.zero) + c
    if coeff:
        d[zm] = coeff
    elif zm in d:
        del d[zm]


def smp_sub_ground(d: smp[Er], c: Er, n: int, domain: Domain[Er]) -> smp[Er]:
    # Subtract a ground coefficient from the constant term.
    h = d.copy()
    _smp_isub_ground(h, c, n, domain)
    return h


def smp_neg(f: smp[Er], n: int, domain: Domain[Er]) -> smp[Er]:
    # Return the opposite of a sparse polynomial.
    return {mon: -coeff for mon, coeff in f.items() if coeff}


def _smp_isub_ground(d: smp[Er], c: Er, n: int, domain: Domain[Er]) -> None:
    # Subtract a ground coefficient from a sparse polynomial in place.
    if not c:
        return

    zm: monom = (0,) * n
    coeff = d.get(zm, domain.zero) - c
    if coeff:
        d[zm] = coeff
    elif zm in d:
        del d[zm]


def smp_rsub_ground(d: smp[Er], c: Er, n: int, domain: Domain[Er]) -> smp[Er]:
    # Subtract the sparse polynomial from a ground coefficient.
    h = d.copy()
    _smp_irsub_ground(h, c, n, domain)
    return h


def _smp_irsub_ground(d: smp[Er], c: Er, n: int, domain: Domain[Er]) -> None:
    # Subtract a sparse polynomial from a ground coefficient in place.
    for mon, coeff in list(d.items()):
        if coeff:
            d[mon] = -coeff
        else:
            del d[mon]
    _smp_iadd_ground(d, c, n, domain)


def smp_mul_ground(d: smp[Er], x: Er, n: int, domain: Domain[Er]) -> smp[Er]:
    # Multiply every coefficient by a ground element.
    h = d.copy()
    _smp_imul_ground(h, x, n, domain)
    return h


def _smp_imul_ground(d: smp[Er], x: Er, n: int, domain: Domain[Er]) -> None:
    # Multiply every coefficient by a ground element in place.
    if not x:
        d.clear()
        return

    for mon, coeff in list(d.items()):
        coeff *= x
        if coeff:
            d[mon] = coeff
        else:
            del d[mon]


def smp_imul_num(d: smp[Er], c: Er, n: int, domain: Domain[Er]) -> smp[Er]:
    # Multiply every coefficient by a ground element in place.
    if not c:
        d.clear()
        return d

    for mon in list(d):
        coeff = d[mon] * c
        if coeff:
            d[mon] = coeff
        else:
            del d[mon]

    return d


def smp_quo_ground(d: smp[Er], x: Er, n: int, domain: Domain[Er]) -> smp[Er]:
    # Divide exactly divisible coefficients by a ground element, discard non exactly
    # divisible coefficients.
    h = d.copy()
    _smp_iquo_ground(h, x, n, domain)
    return h


def _smp_iquo_ground(d: smp[Er], x: Er, n: int, domain: Domain[Er]) -> None:
    # Divide exactly divisible coefficients by a ground element in place.
    for mon, coeff in list(d.items()):
        try:
            quotient = domain.exquo(coeff, x)
        except ExactQuotientFailed:
            del d[mon]
            continue
        if quotient:
            d[mon] = quotient
        else:
            del d[mon]


def smp_trunc_ground(d: smp[Er], p: Er, n: int, domain: Domain[Er]) -> smp[Er]:
    # Reduce coefficients modulo a ground element.
    h = d.copy()
    _smp_itrunc_ground(h, p, n, domain)
    return h


def _smp_itrunc_ground(d: smp[Er], p: Er, n: int, domain: Domain[Er]) -> None:
    # Reduce coefficients modulo a ground element in place.
    if domain.is_ZZ:
        t = domain.quo(p, domain.convert(2))
        for mon, coeff in list(d.items()):
            coeff = domain.rem(coeff, p)
            c = coeff - t
            if domain.is_positive(c):
                coeff = coeff - p
            if coeff:
                d[mon] = coeff
            else:
                del d[mon]
    else:
        for mon, coeff in list(d.items()):
            coeff = domain.rem(coeff, p)
            if coeff:
                d[mon] = coeff
            else:
                del d[mon]


def smp_subs(
    d: smp[Er], subs_dict: Mapping[int, Er], n: int, domain: Domain[Er]
) -> smp[Er]:
    # Substitute selected variables while preserving monomial dimensions.
    h: smp[Er] = {}

    for mon, coeff in d.items():
        new_coeff = coeff
        new_mon_list = list(mon)

        for i, value in subs_dict.items():
            exp = mon[i]
            if exp > 0:
                new_coeff *= value**exp
            new_mon_list[i] = 0

        if new_coeff:
            new_mon = tuple(new_mon_list)
            coeff = h.get(new_mon, domain.zero) + new_coeff
            if coeff:
                h[new_mon] = coeff
            elif new_mon in h:
                del h[new_mon]

    return h


def smp_subs_drop(
    d: smp[Er], subs_dict: Mapping[int, Er], n: int, domain: Domain[Er]
) -> smp[Er]:
    # Substitute selected variables and remove their monomial coordinates.
    h: smp[Er] = {}
    kept_indices = [i for i in range(n) if i not in subs_dict]

    for mon, coeff in d.items():
        new_coeff = coeff

        for i, value in subs_dict.items():
            exp = mon[i]
            if exp > 0:
                new_coeff *= value**exp

        if new_coeff:
            new_mon = tuple(mon[i] for i in kept_indices)
            coeff = h.get(new_mon, domain.zero) + new_coeff
            if coeff:
                h[new_mon] = coeff
            elif new_mon in h:
                del h[new_mon]

    return h


def smp_evaluate(
    d: smp[Er], eval_dict: Mapping[int, Er], n: int, domain: Domain[Er]
) -> Er:
    # Evaluate all variables and return an element of the ground domain.
    result = domain.zero

    for mon, coeff in d.items():
        mon_value = domain.one
        for i in range(n):
            exp = mon[i]
            if exp > 0:
                mon_value *= eval_dict[i] ** exp

        result += coeff * mon_value

    return result


def smp_leading_expv(
    d: smp[Er], n: int, domain: Domain[Er], order: MonomialOrder = lex
) -> monom | None:
    # Return the greatest exponent tuple for the selected monomial order.
    if not d:
        return None
    elif order is lex:
        return max(d)
    else:
        return max(d, key=order)


def smp_get_coeff(d: smp[Er], expv: monom | None, n: int, domain: Domain[Er]) -> Er:
    # Return the coefficient of an exponent tuple or zero when absent.
    if expv is None:
        return domain.zero
    return d.get(expv, domain.zero)


def smp_LC(d: smp[Er], n: int, domain: Domain[Er], order: MonomialOrder = lex) -> Er:
    # Return the leading coefficient for the selected monomial order.
    return smp_get_coeff(d, smp_leading_expv(d, n, domain, order), n, domain)


def smp_LM(d: smp[Er], n: int, domain: Domain[Er], order: MonomialOrder = lex) -> monom:
    # Return the leading exponent tuple, using the zero monomial for zero.
    expv = smp_leading_expv(d, n, domain, order)
    if expv is None:
        return (0,) * n
    return expv


def smp_LT(
    d: smp[Er], n: int, domain: Domain[Er], order: MonomialOrder = lex
) -> tuple[monom, Er]:
    # Return the leading exponent tuple and coefficient.
    expv = smp_leading_expv(d, n, domain, order)
    if expv is None:
        return ((0,) * n, domain.zero)
    return (expv, smp_get_coeff(d, expv, n, domain))


def smp_leading_monom(
    d: smp[Er], n: int, domain: Domain[Er], order: MonomialOrder = lex
) -> smp[Er]:
    # Return the leading monomial as a one-term sparse polynomial.
    expv = smp_leading_expv(d, n, domain, order)
    if expv:
        return {expv: domain.one}
    return {}


def smp_leading_term(
    d: smp[Er], n: int, domain: Domain[Er], order: MonomialOrder = lex
) -> smp[Er]:
    # Return the leading term as a one-term sparse polynomial.
    expv = smp_leading_expv(d, n, domain, order)
    if expv is None:
        return {}
    return {expv: d[expv]}


def smp_const(d: smp[Er], n: int, domain: Domain[Er]) -> Er:
    # Return the constant coefficient of a sparse polynomial.
    return smp_get_coeff(d, (0,) * n, n, domain)


def smp_coeff(d: smp[Er], monomial: smp[Er], n: int, domain: Domain[Er]) -> Er:
    # Return the coefficient of a monomial represented by a sparse dictionary.
    terms = list(monomial.items())
    if len(terms) == 1:
        mon, coeff = terms[0]
        if coeff == domain.one:
            return smp_get_coeff(d, mon, n, domain)
    raise ValueError(f"expected a monomial, got {monomial}")


def _smp_term_div(
    n: int, domain: Domain[Er]
) -> Callable[[tuple[monom, Er], tuple[monom, Er]], tuple[monom, Er] | None]:
    # Return a function for exact polynomial term division.
    zm: monom = (0,) * n
    monomial_div = _get_monomial_div(n)

    def smp_term_div(
        term1: tuple[monom, Er], term2: tuple[monom, Er]
    ) -> tuple[monom, Er] | None:
        mon1, coeff1 = term1
        mon2, coeff2 = term2
        mon: monom | None
        if mon2 == zm:
            mon = mon1
        else:
            mon = monomial_div(mon1, mon2)
            if mon is None:
                return None

        try:
            return mon, domain.exquo(coeff1, coeff2)
        except ExactQuotientFailed:
            return None

    return smp_term_div


def smp_quo_term(
    d: smp[Er], term: tuple[monom, Er], n: int, domain: Domain[Er]
) -> smp[Er]:
    # Divide every exactly divisible term by a fixed polynomial term.
    h: smp[Er] = {}
    smp_term_div = _smp_term_div(n, domain)
    for f_term in d.items():
        q_term = smp_term_div(f_term, term)
        if q_term is not None:
            mon, coeff = q_term
            if coeff:
                h[mon] = coeff
    return h


def smp_div_list(
    d: smp[Er],
    gs: Sequence[smp[Er]],
    n: int,
    domain: Domain[Er],
    order: MonomialOrder = lex,
) -> tuple[list[smp[Er]], smp[Er]]:
    # Divide a sparse polynomial by a list of sparse polynomials.
    if not all(gs):
        raise ZeroDivisionError("polynomial division")

    qs: list[smp[Er]] = [{} for _ in gs]
    lts = [smp_LT(g, n, domain, order) for g in gs]
    f = d.copy()
    r: smp[Er] = {}
    smp_term_div = _smp_term_div(n, domain)

    while f:
        divoccurred = False
        lm_f = smp_leading_expv(f, n, domain, order)
        if lm_f is None:
            break

        for i, (g, lt_g) in enumerate(zip(gs, lts)):
            q_term = smp_term_div((lm_f, f[lm_f]), lt_g)
            if q_term is not None:
                q_mon, c = q_term
                smp_iadd_monom(qs[i], q_term, n, domain)
                smp_iadd_poly_monom(f, g, (q_mon, -c), n, domain)
                divoccurred = True
                break

        if not divoccurred:
            smp_iadd_monom(r, (lm_f, f[lm_f]), n, domain)
            del f[lm_f]

    return qs, r


def smp_rem_list(
    d: smp[Er],
    gs: Sequence[smp[Er]],
    n: int,
    domain: Domain[Er],
    order: MonomialOrder = lex,
) -> smp[Er]:
    # Compute the remainder after division by a list of polynomials.
    if not all(gs):
        raise ZeroDivisionError("polynomial division")

    monomial_mul = _get_monomial_mul(n)
    r: smp[Er] = {}
    lts = [smp_LT(g, n, domain, order) for g in gs]
    f = d.copy()
    smp_term_div = _smp_term_div(n, domain)

    while f:
        lm_f = smp_leading_expv(f, n, domain, order)
        if lm_f is None:
            break
        lt_f = (lm_f, f[lm_f])

        for g, lt_g in zip(gs, lts):
            q_term = smp_term_div(lt_f, lt_g)
            if q_term is not None:
                q_mon, c = q_term
                for mon, coeff in g.items():
                    p_mon = monomial_mul(mon, q_mon)
                    c1 = f.get(p_mon, domain.zero) - c * coeff
                    if c1:
                        f[p_mon] = c1
                    elif p_mon in f:
                        del f[p_mon]
                break
        else:
            smp_iadd_monom(r, lt_f, n, domain)
            del f[lm_f]

    return r


def smp_compose(
    d: smp[Er],
    reps: list[tuple[int, smp[Er]]],
    initial_poly: smp[Er],
    n: int,
    domain: Domain[Er],
) -> smp[Er]:
    # Compose a sparse polynomial with replacement polynomials.
    poly = initial_poly.copy()

    for mon, coeff in d.items():
        mon_list = list(mon)
        subpoly: smp[Er] = {(0,) * n: domain.one}

        for i, g in reps:
            exp, mon_list[i] = mon_list[i], 0
            if exp:
                subpoly = smp_mul(
                    subpoly, smp_pow_generic(g, exp, domain, n), domain, n
                )

        smp_iadd_poly_monom(poly, subpoly, (tuple(mon_list), coeff), n, domain)

    return poly


def _smp_symmetric_poly(k: int, n: int, domain: Domain[Er]) -> smp[Er]:
    # Build the elementary symmetric polynomial of degree k.
    if k < 0 or k > n:
        raise ValueError(f"Cannot generate symmetric polynomial of order {k}")
    elif not k:
        return {(0,) * n: domain.one}

    h: smp[Er] = {}
    for subset in combinations(range(n), k):
        mon = tuple(int(i in subset) for i in range(n))
        h[mon] = domain.one
    return h


def smp_symmetrize(
    d: smp[Er], n: int, domain: Domain[Er], order: MonomialOrder = lex
) -> tuple[smp[Er], smp[Er], list[smp[Er]]]:
    # Rewrite a symmetric polynomial in elementary symmetric polynomials.
    f = d.copy()

    if not n:
        return f, {}, []

    polys = [_smp_symmetric_poly(i + 1, n, domain) for i in range(n)]
    poly_powers: dict[tuple[int, int], smp[Er]] = {}

    def get_poly_power(i: int, exp: int) -> smp[Er]:
        if (i, exp) not in poly_powers:
            poly_powers[(i, exp)] = smp_pow_generic(polys[i], exp, domain, n)
        return poly_powers[(i, exp)]

    indices = list(range(n - 1))
    weights = list(range(n, 0, -1))

    symmetric: smp[Er] = {}

    while f:
        height = -1
        mc: tuple[monom, Er] | None = None

        if order is lex:
            terms = sorted(f.items(), key=lambda term: term[0], reverse=True)
        else:
            terms = sorted(f.items(), key=lambda term: order(term[0]), reverse=True)

        for mon, coeff in terms:
            if all(mon[i] >= mon[i + 1] for i in indices):
                mon_height = max(
                    weight * mon_exp for weight, mon_exp in zip(weights, mon)
                )

                if mon_height > height:
                    height = mon_height
                    mc = mon, coeff

        if mc is None:
            break
        mon, coeff = mc

        exps = []
        for m1, m2 in zip(mon, mon[1:] + (0,)):
            exps.append(m1 - m2)

        smp_iadd_monom(symmetric, (tuple(exps), coeff), n, domain)

        h: smp[Er] = {(0,) * n: coeff}
        for i, exp in enumerate(exps):
            h = smp_mul(h, get_poly_power(i, exp), domain, n)

        f = smp_sub(f, h, domain, n)

    return symmetric, f, polys


def smp_square(d: smp[Er], domain: Domain[Er], n: int) -> smp[Er]:
    # Square a sparse polynomial using cross and diagonal terms.
    zero = domain.zero
    h: smp[Er] = {}
    get = h.get
    mons = list(d.keys())
    monomial_mul = _get_monomial_mul(n)
    for i, mon1 in enumerate(mons):
        coeff1 = d[mon1]
        for j in range(i):
            mon2 = mons[j]
            mon = monomial_mul(mon1, mon2)
            coeff = get(mon, zero) + coeff1 * d[mon2]
            if coeff:
                h[mon] = coeff
            elif mon in h:
                del h[mon]

    for mon, coeff in list(h.items()):
        coeff *= 2
        if coeff:
            h[mon] = coeff
        else:
            del h[mon]

    get = h.get
    for mon, coeff in d.items():
        mon2 = monomial_mul(mon, mon)
        coeff = get(mon2, zero) + coeff**2
        if coeff:
            h[mon2] = coeff
        elif mon2 in h:
            del h[mon2]

    return h


def smp_pow_generic(d: smp[Er], exp: int, domain: Domain[Er], n: int) -> smp[Er]:
    # Raise a sparse polynomial to a power by binary exponentiation.
    if exp == 0:
        if not d:
            raise ValueError("0**0")
        um: monom = (0,) * n
        return {um: domain.one}
    elif exp < 0:
        raise ValueError(f"exponent must be a non-negative integer, got {exp}")
    if not d:
        return {}

    zm: monom = (0,) * n
    h: smp[Er] = {zm: domain.one}
    f = d

    while True:
        if exp & 1:
            h = smp_mul(h, f, domain, n)
            exp -= 1
            if not exp:
                break

        f = smp_square(f, domain, n)
        exp = exp // 2

    return h


def smp_pow_multinomial(d: smp[Er], exp: int, domain: Domain[Er], n: int) -> smp[Er]:
    # Raise a sparse polynomial to a power by multinomial expansion.
    if exp == 0:
        if not d:
            raise ValueError("0**0")
        um: monom = (0,) * n
        return {um: domain.one}
    elif exp < 0:
        raise ValueError(f"exponent must be a non-negative integer, got {exp}")

    if not d:
        return {}

    multinomials = multinomial_coefficients(len(d), exp).items()
    zm: monom = (0,) * n
    terms = d.items()
    zero = domain.zero
    h: smp[Er] = {}
    mulpow = _get_monomial_mulpow(n)

    for multinomial, multinomial_coeff in multinomials:
        p_mon = zm
        c = domain.convert(multinomial_coeff)
        for term_exp, (mon, coeff) in zip(multinomial, terms):
            if term_exp:
                p_mon = mulpow(p_mon, mon, term_exp)
                c *= coeff**term_exp

        coeff = h.get(p_mon, zero) + c

        if coeff:
            h[p_mon] = coeff
        elif p_mon in h:
            del h[p_mon]

    return h

